import{z as B,x as i,o as r,c as p,q as l,j as n,D as t,d as E,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"DFS 与边分类","description":"","frontmatter":{"title":"DFS 与边分类","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dfs-edge-types.md","filePath":"cs/dfs-edge-types.md","lastUpdated":1791413859000}'),A={name:"cs/dfs-edge-types.md"};function u(D,a,f,S,h,m){const s=i("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="dfs-与边分类" tabindex="-1">DFS 与边分类 <a class="header-anchor" href="#dfs-与边分类" aria-label="Permalink to &quot;DFS 与边分类&quot;">​</a></h1><div class="epigraph"><p>深度优先的进出时刻把每条边标成树边、反向边、前向边或横叉边；环与否写在反向边上。</p><footer>—— 据 Tarjan, Depth-First Search and Linear Graph Algorithms, 1972；CLRS 第 22 章整理</footer></div><p>上一课<a href="/cs/bfs-unweighted">BFS 与无权最短路</a>用队列得到无权距离。本课不重做分层。缺口是：图上还有<strong>结构</strong>——有没有环、哪些边连回祖先、哪些边连到另一棵树上的点。栈式深入加上发现/完成时刻，才能给边分类。本课只钉 DFS 与四类边（无向图上收缩成树边与反向边）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BFS 树几乎不谈回边：同一层或邻层的非树边不回答「是否有向环」。缺口是时间戳：\\(u.d\\) 发现、\\(u.f\\) 完成，括号性质：两个区间要么嵌套要么不相交。树边进入白邻；反向边指向祖先（有向环的证据）；前向边指向已完成的真后代；横叉边指向既非祖先也非后代的已发现点。</p><p><span class="marginnote">直觉类比：灰色的链就是你脚下正在走的递归路径——白是没去过，灰是「还在当前栈里」，黑是「已彻底逛完」。指向灰等于踩到自己没抬走的脚印，这就是环的证据，也是反向边的全部含义。</span></p><p><a href="/cs/dag-repr">DAG 预备</a>说过无环可排序；本课给出检测：有向图有环当且仅当 DFS 发现反向边。拓扑序本身下一课才写。</p><h3 id="递归栈就是那条路" tabindex="-1">递归栈就是那条路 <a class="header-anchor" href="#递归栈就是那条路" aria-label="Permalink to &quot;递归栈就是那条路&quot;">​</a></h3><p>DFS 的灰色顶点链是当前从根到 \\(u\\) 的路径。指向灰色即反向。指向黑色则按时间戳分成前向与横叉。不要用「看起来像回头」的口语代替颜色与时刻。</p><p><span class="marginnote">Tarjan 用 DFS 做强连通与双连通；本课只取边分类与括号定理，强连通不展开。CLRS 22.3 的分类是后课拓扑、桥与割点的共同前置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个白点开一次 <code>DFS-VISIT</code>：置发现时刻，扫邻接表，递归白邻（树边），最后置完成时刻。全图 \\(\\Theta(V+E)\\)。无向图：每条边只分类一次，非树边都是反向边（连祖先）。</p>',12)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%99%BD%E9%82%BB%22%5D%20--%3E%20TREE%5B%22%E6%A0%91%E8%BE%B9%22%5D%0A%20%20G%5B%22%E7%81%B0%E9%82%BB%22%5D%20--%3E%20BACK%5B%22%E5%8F%8D%E5%90%91%E8%BE%B9%22%5D%0A%20%20B%5B%22%E9%BB%91%E9%82%BB%22%5D%20--%3E%20FW%5B%22%E5%89%8D%E5%90%91%E6%88%96%E6%A8%AA%E5%8F%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"括号：\\(u\\) 是 \\(v\\) 祖先当且仅当 \\([v.d,v.f]\\subset[u.d,u.f]\\)。后课拓扑按完成时刻降序，依据就在这里。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：设 \\(u\\) 的区间是 \\([6,9]\\)。若 \\(v\\) 的区间是 \\([7,8]\\)，完全嵌在里面，\\(v\\) 是 \\(u\\) 的后代，\\(u\\to v\\) 是前向边；若 \\(v\\) 的区间是 \\([1,5]\\)，在 \\(u\\) 开始前就已完结，那就是横叉边。括号性质保证区间只有嵌套与不相交两种，\\([1,8]\\) 对 \\([2,9]\\) 这种半重叠在 DFS 里根本不会出现。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[E("边分类依赖"),e("strong",null,"第一次"),E(" DFS 森林。另一次不同的顶点序可以换树边集合，但「有无反向边」对有向环不变。无向图的横叉在标准分类里不出现，因为先发现的端点会把边当树边或反向边用掉。")],-1)),a[7]||(a[7]=e("p",null,"不要把 BFS 的非树边叫反向边：那不是 DFS 时刻。两种遍历的树都是生成林，职责不同。",-1)),a[8]||(a[8]=e("p",null,"上面那张图是「扫到邻点时按颜色一查」的速查表；这张回答更细的一步：邻点是黑色时，前向边和横叉边怎么用时刻区间区分开。",-1)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%BB%8E%20u%20%E6%89%AB%E5%88%B0%E9%82%BB%E7%82%B9%20v%20%E5%B7%B2%E6%98%AF%E9%BB%91%E8%89%B2%22%5D%20--%3E%20CMP%5B%22%E6%AF%94%E8%BE%83%20u%20%E4%B8%8E%20v%20%E7%9A%84%E5%8F%91%E7%8E%B0%20%E5%AE%8C%E6%88%90%E5%8C%BA%E9%97%B4%22%5D%0A%20%20CMP%20--%3E%20NEST%7B%22v%20%E7%9A%84%E5%8C%BA%E9%97%B4%E5%B5%8C%E5%9C%A8%20u%20%E5%86%85%22%7D%0A%20%20NEST%20--%20%22%E6%98%AF%20v.d%20%E5%A4%A7%E4%BA%8E%20u.d%20%E4%B8%94%20v.f%20%E5%B0%8F%E4%BA%8E%20u.f%22%20--%3E%20FW%5B%22%E5%89%8D%E5%90%91%E8%BE%B9%20v%20%E6%98%AF%E7%9C%9F%E5%90%8E%E4%BB%A3%22%5D%0A%20%20NEST%20--%20%22%E5%90%A6%20%E5%8C%BA%E9%97%B4%E4%B8%8D%E7%9B%B8%E4%BA%A4%22%20--%3E%20CROSS%5B%22%E6%A8%AA%E5%8F%89%E8%BE%B9%20v%20%E5%9C%A8%E5%8F%A6%E4%B8%80%E5%AD%90%E6%A0%91%20%E6%97%A9%E5%B7%B2%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=l('<p><span class="marginnote">常见误区：把无向图的每条边当两条有向边各分类一次。实际上每条无向边只被看一次：非树边必是反向边——先遇到的端点会把这条边「用掉」当树边，剩下的指向只可能落回祖先，所以无向图没有前向边和横叉边。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算最短路。不写强连通分量的第二次 DFS。不引入桥与割点的 low 值。有向图的横叉边不单独构成环。后课拓扑排序假定会看完成时刻或入度，不再从颜色讲起。</p><p>后课默认：DFS 给出 \\(d/f\\) 与边分类；有向环 \\(\\Leftrightarrow\\) 反向边。拓扑是下一课把 DAG 变成线性序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DFS 用发现/完成时刻给边分类；括号嵌套即祖先。</li><li>有向环当且仅当存在反向边。</li><li>代价仍 \\(\\Theta(V+E)\\)；不给出距离。</li><li>出处：Tarjan, 1972；CLRS 第 22.3 节。</li></ul>',6))])}const C=B(A,[["render",u]]);export{T as __pageData,C as default};
